import{_ as d,a0 as r,w as i,s as l,ao as a,I as n,x as t,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"tespeed - 测试网速的Python工具 | LCTT x X-CMD","titleTemplate":false,"description":"tespeed - 测试网速的Python工具 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"tespeed - 测试网速的Python工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"tespeed - 测试网速的Python工具 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150202 tespeed - Python Tool To Test Your Internet Speed","title":"tespeed - 测试网速的Python工具","tag":"201504","desc":""},"relativePath":"201504/20150202 tespeed - Python Tool To Test Your Internet Speed.md","filePath":"[post].md"}'),h={name:"201504/20150202 tespeed - Python Tool To Test Your Internet Speed.md"};function g(m,e,y,u,T,x){const p=r("Link");return i(),l("div",null,[e[13]||(e[13]=a(`<h1 id="tespeed-测试网速的python工具" tabindex="-1">tespeed - 测试网速的Python工具 <a class="header-anchor" href="#tespeed-测试网速的python工具" aria-label="Permalink to “tespeed - 测试网速的Python工具”">​</a></h1><p>许多电脑呆子知道可以用<strong>speedtest.net</strong>测试网速，但是这个不能在测试中给你足够的控制。Linux用户喜欢在终端中输入命令来完成任务，至少我就是这样的。</p><p>tespeed是一款有很多特性的python工具，可以在终端在测试网速。根据文档说明，它利用了speedtest.net的服务器，但是用户可以手动指定。</p><p>最初作者用php语言写了tespeed工具，并且证明了ISP提供的网络远低于它广告中所说的那样。但是事情并不是一直如他们想的那样，因此作者移植他的php脚本到python中，并且他的工具在github中已经有180个star了。</p><p>It means <strong>alot</strong>。</p><h3 id="如何在linux中测试tespeed" tabindex="-1">如何在linux中测试tespeed <a class="header-anchor" href="#如何在linux中测试tespeed" aria-label="Permalink to “如何在linux中测试tespeed”">​</a></h3><p>在你电脑上运行这个python程序前先确保系统已经满足了这个工具的依赖。tespeed依赖下面两个包：</p><ul><li>lxml</li><li>SocksiPy</li></ul><p>你可以用pip包管理系统来安装lxml，只要用下面的命令就行。</p><pre><code>pip install lxml
</code></pre><p>现在我们需要输入下面的命令来下载安装SocksiPy。</p><pre><code>wget http://sourceforge.net/projects/socksipy/files/socksipy/SocksiPy%201.00/SocksiPy.zip/
</code></pre><p>下载完成后 解压<strong>SocksiPy.zip</strong>并运行下面的命令来克隆tespeed仓库到你本地机器中。</p><pre><code>git clone https://github.com/Janhouse/tespeed.git
</code></pre><p>接着把SocksiPy文件夹放到你克隆下来的tespeed项目中。现在我们要像截图那样在SocksiPy中的创建一个叫<strong><strong>init</strong>.py</strong>的空文件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/tespeed1.png" alt="simple trick to make tespeed work"></p><p>现在我们已经解决了项目的依赖问题，我们可以用下面的命令运行了。</p><pre><code>python tespeed.py
</code></pre><p>接下来就会发生一些神奇的事了。程序会测试你的下载和上传速度并且在你的终端中用漂亮的颜色显示出来。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/tespeed2.png" alt="testing download and upload speed with tespeed python application"></p><p>在tespeed中有很多选项，如<strong>-ls</strong>来列出服务器，<strong>-p</strong>来指定代理服务器， <strong>-s</strong>来阻止调试(STDERR)输出, 还有很多我们会在本教程中探索。</p><p>如果你想要结果显示成MB，你可以在<strong>python tespeed.py</strong> 后面接上选项 <strong>-mib</strong>。</p><pre><code>python tespeed.py -mib
</code></pre><p>在你使用了-mib选项后你可以看到计量网速的单位改变了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/tespeed3.png" alt="testing internet speed with tespeed python application"></p><p>我非常喜欢用的一个选项是-w，它可以把标准输出转化成CSV格式。</p><pre><code>python tespeed.py -w
</code></pre><p>使用下面的命令来列出服务器。</p><pre><code>python tespeed -ls
</code></pre><p>运行上面的命令后，你会看到可以用于测试上传和下载速度的服务器列表。我的列表非常长，所以我不会在教程中共享了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>tespeed的确是一款帮助用户在终端中测试上传和下载速度的高性能python脚本。它支持很多的选项并且你可以指定列表中你想使用的服务器。继续使用tespeed并在留言区写下你们的体验吧。</p><hr>`,33)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://linoxide.com/tools/tespeed-python-tool-test-internet-speed/"},{default:s(()=>[...e[0]||(e[0]=[t("http://linoxide.com/tools/tespeed-python-tool-test-internet-speed/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=t("作者：",-1)),o(p,{href:"http://linoxide.com/author/oltjano/"},{default:s(()=>[...e[2]||(e[2]=[t("Oltjano Terpollari",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:s(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),o(p,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),o(p,{href:"http://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const k=d(h,[["render",g]]);export{c as __pageData,k as default};
